class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        map<int, int> nxt;
        stack<int> st;
        for (int i = 0; i < (int)nums2.size(); i++) {
            while (!st.empty() && st.top() < nums2[i]) {
                nxt[st.top()] = nums2[i];
                st.pop();
            }
            st.push(nums2[i]);
        }
        vector<int> res;
        for (int x : nums1) res.push_back(nxt.count(x) ? nxt[x] : -1);
        return res;
    }
};
